const listAutomationDeliveries = `-- name: ListAutomationDeliveries :many
SELECT id, task_id, source_id, policy_id, revision, status, value, credential_ref, created_at FROM automation_deliveries WHERE task_id=? ORDER BY created_at,id
`

func (q *Queries) ListAutomationDeliveries(ctx context.Context, taskID string) ([]AutomationDelivery, error) {
	rows, err := q.db.QueryContext(ctx, listAutomationDeliveries, taskID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AutomationDelivery{}
	for rows.Next() {
		var i AutomationDelivery
		if err := rows.Scan(
			&i.ID,
			&i.TaskID,
			&i.SourceID,
			&i.PolicyID,
			&i.Revision,
			&i.Status,
			&i.Value,
			&i.CredentialRef,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

